// HU-08 T04 - Valida los query params del webhook GET /urbanpulse/riesgo-predictivo.
//
// El ticket pide consultar la API "por zona y franja", asi que el unico
// parametro de entrada es franja (una de las 3 que usa el modelo, ver
// ml/api/main.py FRANJAS_VALIDAS). "dia" no es un parametro del caller: se
// calcula aqui mismo como "hoy" en hora de Lima (UTC-5 fijo, Lima no usa
// horario de verano) y se usa igual para el campo "fecha" de POST /predict
// y para la clave de cache_riesgo_predictivo -- asi no hay que validar una
// fecha arbitraria que el caller podria mandar mal formada.
const FRANJAS_VALIDAS = ['manana', 'tarde', 'noche'];

const query = ($json && $json.query) || {};
const errores = [];

const franjaCruda = typeof query.franja === 'string' ? query.franja : '';
const franja = franjaCruda.trim().toLowerCase();
if (!FRANJAS_VALIDAS.includes(franja)) {
  errores.push(`franja debe ser una de: ${FRANJAS_VALIDAS.join(', ')}`);
}

const hoyLimaMs = Date.now() - 5 * 60 * 60 * 1000;
const dia = new Date(hoyLimaMs).toISOString().slice(0, 10);

return [{
  json: {
    valido: errores.length === 0,
    franja,
    dia,
    errores,
  },
}];

// HU-08 T04 - Respuesta de error para parametros invalidos.
return [{
  json: {
    http_code: 400,
    response_body: {
      error: 'parametros_invalidos',
      detalle: $json.errores,
    },
  },
}];

parameters.query:
SELECT payload, generado_en
FROM cache_riesgo_predictivo
WHERE franja = $1;

parameters.jsCode:
// HU-08 T04 - Decide si la fila de cache_riesgo_predictivo (si existe) sigue
// vigente (menos de 15 min desde que se guardo). "Leer cache" corre con
// onError continueRegularOutput, asi que un fallo de Neon aqui NO rompe el
// webhook: simplemente se trata como "no hay cache" y se sigue al calculo
// en vivo.
const VIGENCIA_MIN = 15;

const params = $('Validar parámetros').first().json;
const filas = $input.all().map((i) => i.json);
const fila = filas.find((f) => f && !f.error && f.payload !== undefined && f.payload !== null);

let vigente = false;
let payload = null;

if (fila) {
  const generado = new Date(fila.generado_en);
  if (!isNaN(generado.getTime())) {
    const antiguedadMin = (Date.now() - generado.getTime()) / 60000;
    vigente = antiguedadMin >= 0 && antiguedadMin < VIGENCIA_MIN;
  }
  payload = fila.payload;
}

return [{
  json: {
    franja: params.franja,
    dia: params.dia,
    cache_vigente: vigente,
    cache_payload: payload,
  },
}];

// HU-08 T04 - Responde con el payload cacheado tal cual se guardo (el
// contrato 4.2 no cambia por venir de cache: es la misma respuesta que ya se
// habia calculado hace menos de 15 min).
return [{
  json: {
    http_code: 200,
    response_body: $json.cache_payload,
  },
}];

// HU-08 T04 - Sonda de disponibilidad del modelo, mismo patron que "Sondar
// n8n y la API de riesgo" (HU-13 T01): GET /health sin credenciales (el
// endpoint es publico, ver ml/api/main.py - no llama a _verificar_api_key),
// con timeout corto para no colgar el webhook si la API esta caida.
const URL_API_RIESGO = 'https://urbanpulse-api.xq33kajky1yy6.us-east-1.cs.amazonlightsail.com';
const TIMEOUT_MS = 5000;

let disponible = false;
let salud = null;
let error = null;

try {
  salud = await this.helpers.httpRequest({
    method: 'GET',
    url: `${URL_API_RIESGO}/health`,
    timeout: TIMEOUT_MS,
    json: true,
  });
  disponible = true;
} catch (e) {
  error = String((e && e.message) || e).slice(0, 200);
}

return [{ json: { disponible, salud, error } }];

// HU-08 T04 - El /health de la API de riesgo no respondio (API caida o
// timeout). No se calcula nada mas: mejor fallar explicito que inventar un
// panel con datos a medias.
return [{
  json: {
    http_code: 503,
    response_body: {
      error: 'modelo_no_disponible',
      detalle: 'La API del modelo de riesgo vial (HT-46) no respondio a /health.',
    },
  },
}];

// HU-08 T04 - Junta las filas de "Zonas y variables" (una por zona) en el
// unico cuerpo que espera POST /predict (contrato de ml/api/main.py:
// PredictRequest = {franja, fecha, zonas: [...]}, con zonas.length entre 1 y
// MAX_ZONAS=200). tipo_via y severidad_media no se mandan: severidad_media la
// calcula la API internamente (severidad_por_zona.json) y tipo_via no se usa
// en el modelo actual.
//
// zonas_meta guarda, por zona_id, los datos crudos (lat/lng/distrito y las
// 3 variables) que "Armar respuesta contrato 4.2" necesita para el contrato
// final y para traducir "motivos" a texto legible -- /predict no los
// devuelve, solo nivel/probabilidad/motivos genericos.
const MAX_ZONAS = 200;

const params = $('Validar parámetros').first().json;
const filas = $input.all().map((i) => i.json).filter((f) => f && !f.error);

const zonas = filas.map((f) => ({
  zona_id: f.zona_id,
  distrito: f.distrito || null,
  siniestros_12m: Number(f.siniestros_12m) || 0,
  congestion_media: Number(f.congestion_media) || 0,
  reportes_30d: Number(f.reportes_30d) || 0,
}));

const zonasMeta = {};
for (const f of filas) {
  zonasMeta[f.zona_id] = {
    latitude: typeof f.latitude === 'number' ? f.latitude : Number(f.latitude),
    longitude: typeof f.longitude === 'number' ? f.longitude : Number(f.longitude),
    distrito: f.distrito || null,
    siniestros_12m: Number(f.siniestros_12m) || 0,
    congestion_media: Number(f.congestion_media) || 0,
    reportes_30d: Number(f.reportes_30d) || 0,
  };
}

return [{
  json: {
    franja: params.franja,
    dia: params.dia,
    zonas,
    zonas_meta: zonasMeta,
    zonas_invalido: zonas.length === 0 || zonas.length > MAX_ZONAS,
    zonas_motivo_invalido: zonas.length === 0
      ? 'catalogo_vacio'
      : (zonas.length > MAX_ZONAS ? 'catalogo_excede_limite' : null),
  },
}];

// HU-08 T04 - El catalogo de zonas (puntos_monitoreo) esta vacio o supera el
// limite de /predict (MAX_ZONAS=200, ver ml/api/main.py). Hoy la tabla tiene
// muy pocas filas (catalogo curado a mano), asi que este camino no deberia
// dispararse en la practica -- pero si se dispara, es mejor un 500 explicito
// que un 422 crudo de la API o un panel incompleto.
const motivo = $json.zonas_motivo_invalido;

const detalle = motivo === 'catalogo_vacio'
  ? 'La tabla puntos_monitoreo no tiene zonas registradas.'
  : 'La tabla puntos_monitoreo supera el limite de 200 zonas que acepta POST /predict.';

return [{
  json: {
    http_code: 500,
    response_body: {
      error: 'catalogo_de_zonas_invalido',
      detalle,
    },
  },
}];

// HU-08 T04 - POST /predict fallo (API caida, timeout tras reintentos, o
// X-API-Key invalida/ausente -> 401, o 400/422 de validacion). "Llamar
// /predict" corre con onError continueErrorOutput, asi que llegar aqui
// significa que la rama de error de ese nodo se disparo.
return [{
  json: {
    http_code: 503,
    response_body: {
      error: 'prediccion_no_disponible',
      detalle: 'POST /predict de la API del modelo de riesgo vial (HT-46) fallo o no respondio a tiempo.',
    },
  },
}];

// HU-08 T04 - Arma la respuesta final (contrato 4.2) juntando:
//   - "Preparar payload /predict": lat/lng/distrito y las 3 variables por
//     zona (zonas_meta) -- /predict no las devuelve.
//   - "Llamar /predict": model_version y predicciones (zona_id, nivel,
//     probabilidad). Prediccion.motivos de ml/api/main.py es un array fijo
//     de nombres de features, por eso se ignora y se traducen los motivos
//     reales a partir de zonas_meta.
//   - "Sondar /health": fecha de entrenamiento y F1-macro del modelo cargado.
//   - "Último evento de monitoreo": fecha y deriva (null si no hay evento).
//
// HU-10 T05 / contrato C5: f1_macro es el F1-macro de VALIDACION TEMPORAL
// del modelo que sirve la API (el de MLflow, ver ml/README.md), que /health
// expone. NO se usa f1_real del evento de monitoreo: ese es el F1 medido en
// produccion (HT-49), es otra metrica y hoy llega null por falta de
// predicciones. Si /health no trae el dato, se envia null y la tarjeta
// muestra "Pendiente".
//
// sesgo_ok queda en null a proposito hasta que HT-48 escriba ese tag en MLflow.
const leer = (nodo) => {
  try { return $(nodo).first().json || {}; } catch (e) { return {}; }
};

const UMBRAL_CONGESTION_ALTA = 30; // igual que ml/api/main.py

const pad = (n) => String(n).padStart(2, '0');
const isoLima = (d) => {
  const limaMs = d.getTime() - 5 * 60 * 60 * 1000;
  const l = new Date(limaMs);
  return `${l.getUTCFullYear()}-${pad(l.getUTCMonth() + 1)}-${pad(l.getUTCDate())}`
    + `T${pad(l.getUTCHours())}:${pad(l.getUTCMinutes())}:${pad(l.getUTCSeconds())}-05:00`;
};

const traducirMotivos = (meta) => {
  const motivos = [];
  const siniestros = meta.siniestros_12m || 0;
  const reportes = meta.reportes_30d || 0;

  if (siniestros > 0) {
    motivos.push(`${siniestros} siniestro${siniestros === 1 ? '' : 's'} fatal${siniestros === 1 ? '' : 'es'} en el último año`);
  }
  if ((meta.congestion_media || 0) > UMBRAL_CONGESTION_ALTA) {
    motivos.push('congestión alta');
  }
  if (reportes > 0) {
    motivos.push(`${reportes} reporte${reportes === 1 ? '' : 's'} ciudadano${reportes === 1 ? '' : 's'} en los últimos 30 días`);
  }
  if (motivos.length === 0) {
    motivos.push('sin factores de riesgo relevantes detectados');
  }
  return motivos;
};

// Numero valido o null (acepta "0.332" como texto)
const numeroONull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const prep = leer('Preparar payload /predict');
const pred = leer('Llamar /predict');
const salud = (leer('Sondar /health').salud) || {};

const zonasMeta = prep.zonas_meta || {};
const predicciones = Array.isArray(pred.predicciones) ? pred.predicciones : [];

const eventoFilas = $input.all().map((i) => i.json).filter((f) => f && !f.error);
const evento = eventoFilas.find((f) => Number(f.ok) === 1 && f.tipo) || null;

const fechaEvento = evento && evento.fecha ? new Date(evento.fecha) : null;
const fechaEventoValida = fechaEvento && !isNaN(fechaEvento.getTime());

const zonas = predicciones.map((p) => {
  const meta = zonasMeta[p.zona_id] || {};
  return {
    zona_id: p.zona_id,
    nombre: p.zona_id, // puntos_monitoreo no tiene codigo corto: zona_id = nombre
    distrito: meta.distrito || null,
    lat: Number.isFinite(meta.latitude) ? meta.latitude : null,
    lng: Number.isFinite(meta.longitude) ? meta.longitude : null,
    nivel: p.nivel,
    probabilidad: p.probabilidad,
    motivos: traducirMotivos(meta),
  };
});

const tag = String(pred.model_version || '');

const contrato = {
  generado: isoLima(new Date()),
  modelo: {
    version: tag || null,
    metrica: 'F1-macro (validación temporal)',
    f1_macro: numeroONull(salud.f1_macro),
    entrenado: salud.entrenado || null,
    sesgo_ok: null,
    monitoreo: fechaEventoValida ? {
      fecha: fechaEvento.toISOString().slice(0, 10),
      deriva: evento.tipo === 'modelo.deriva_detectada',
    } : null,
  },
  zonas,
};

return [{
  json: {
    franja: prep.franja,
    dia: prep.dia,
    contrato,
  },
}];

// HU-08 T04 - Responde 200 con el contrato recien calculado, sin importar si
// "Guardar en cache" pudo escribir o no (ese Postgres corre con onError
// continueRegularOutput: un fallo de cache nunca debe tumbar una respuesta
// ya calculada). Por eso el contrato se relee de "Armar respuesta contrato
// 4.2" por nombre, no del $json de entrada (que aqui es la salida, variable,
// del INSERT/UPSERT).
const previo = $('Armar respuesta contrato 4.2').first().json;

return [{
  json: {
    http_code: 200,
    response_body: previo.contrato,
  },
}];
